SELECT e.employee_id, e.employee_no, e.login_id, e.employee_name, e.email, e.department_id, d.department_name, e.active, e.login_fail_count, e.locked_until, e.last_login_at, e.created_at, e.updated_at, e.version FROM employee e JOIN department d ON d.department_id = e.department_id
AND ( LOWER(e.employee_no) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(e.login_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(e.employee_name) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(e.email) LIKE CONCAT('%', LOWER(#{keyword}), '%') )
AND e.department_id = #{departmentId}
AND e.active = #{active}
ORDER BY e.employee_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM employee e


        AND (
            LOWER(e.employee_no) LIKE CONCAT('%', LOWER(#{keyword}), '%')
            OR LOWER(e.login_id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
            OR LOWER(e.employee_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
            OR LOWER(e.email) LIKE CONCAT('%', LOWER(#{keyword}), '%')
        )


        AND e.department_id = #{departmentId}


        AND e.active = #{active}

SELECT er.employee_id, r.role_id, r.role_code, r.role_name FROM employee_role er JOIN `role` r ON r.role_id = er.role_id WHERE er.employee_id IN
#{employeeId}
ORDER BY er.employee_id, r.role_code

mapper.update:
UPDATE employee
SET updated_by = #{actorId},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE employee_id = #{employeeId}
  AND version = #{version}

UPDATE employee
SET login_fail_count = 0,
    locked_until = NULL,
    updated_at = #{now}
WHERE employee_id = #{employeeId}
  AND locked_until IS NOT NULL
  AND locked_until <= #{now}

UPDATE employee
SET login_fail_count = login_fail_count + 1,
    locked_until = CASE
        WHEN login_fail_count + 1 >= #{maxFailures} THEN #{lockedUntil}
        ELSE locked_until
    END,
    updated_at = #{now}
WHERE employee_id = #{employeeId}

UPDATE employee
SET login_fail_count = 0,
    locked_until = NULL,
    last_login_at = #{now},
    updated_at = #{now}
WHERE employee_id = #{employeeId}

UPDATE refresh_token
SET revoked_at = #{now}
WHERE employee_id = #{employeeId}
  AND revoked_at IS NULL
